type IdempotencyReceiptUpsertBulk struct {
	create *IdempotencyReceiptCreateBulk
}

// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.IdempotencyReceipt.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(idempotencyreceipt.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *IdempotencyReceiptUpsertBulk) UpdateNewValues() *IdempotencyReceiptUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(idempotencyreceipt.FieldID)
			}
			if _, exists := b.mutation.PrincipalID(); exists {
				s.SetIgnore(idempotencyreceipt.FieldPrincipalID)
			}
			if _, exists := b.mutation.Operation(); exists {
				s.SetIgnore(idempotencyreceipt.FieldOperation)
			}
			if _, exists := b.mutation.KeyHash(); exists {
				s.SetIgnore(idempotencyreceipt.FieldKeyHash)
			}
			if _, exists := b.mutation.ClaimToken(); exists {
				s.SetIgnore(idempotencyreceipt.FieldClaimToken)
			}
			if _, exists := b.mutation.Fingerprint(); exists {
				s.SetIgnore(idempotencyreceipt.FieldFingerprint)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(idempotencyreceipt.FieldCreatedAt)
			}
			if _, exists := b.mutation.ExpiresAt(); exists {
				s.SetIgnore(idempotencyreceipt.FieldExpiresAt)
			}
		}
	}))
	return u
}

// Ignore sets each column to itself in case of conflict.
// Using this option is equivalent to using:
//
//	client.IdempotencyReceipt.Create().
//		OnConflict(sql.ResolveWithIgnore()).
//		Exec(ctx)
func (u *IdempotencyReceiptUpsertBulk) Ignore() *IdempotencyReceiptUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithIgnore())
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
// Supported only by SQLite and PostgreSQL.
func (u *IdempotencyReceiptUpsertBulk) DoNothing() *IdempotencyReceiptUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.DoNothing())
	return u
}

// Update allows overriding fields `UPDATE` values. See the IdempotencyReceiptCreateBulk.OnConflict
// documentation for more info.
func (u *IdempotencyReceiptUpsertBulk) Update(set func(*IdempotencyReceiptUpsert)) *IdempotencyReceiptUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&IdempotencyReceiptUpsert{UpdateSet: update})
	}))
	return u
}

// SetResponse sets the "response" field.
func (u *IdempotencyReceiptUpsertBulk) SetResponse(v string) *IdempotencyReceiptUpsertBulk {
	return u.Update(func(s *IdempotencyReceiptUpsert) {
		s.SetResponse(v)
	})
}

// UpdateResponse sets the "response" field to the value that was provided on create.
func (u *IdempotencyReceiptUpsertBulk) UpdateResponse() *IdempotencyReceiptUpsertBulk {
	return u.Update(func(s *IdempotencyReceiptUpsert) {
		s.UpdateResponse()
	})
}

// ClearResponse clears the value of the "response" field.
func (u *IdempotencyReceiptUpsertBulk) ClearResponse() *IdempotencyReceiptUpsertBulk {
	return u.Update(func(s *IdempotencyReceiptUpsert) {
		s.ClearResponse()
	})
}

